-- Generated by scripts/build_dataset.py. Apply in the same release as data.json.
-- Dataset version 07d286fdcf78cee0: 3000 startups, 6000 decisions, 2000 survey rows.
begin;
update dataset_manifest set is_current = false where is_current;
insert into dataset_manifest (version, startups_n, decisions_n, survey_n, is_current)
values ('07d286fdcf78cee0', 3000, 6000, 2000, true)
on conflict (version) do update set is_current = true;

insert into allowed_record (record_id, dataset_version)
select 'S' || lpad(g::text, 5, '0'), '07d286fdcf78cee0' from generate_series(1, 3000) g
on conflict (record_id) do update set dataset_version = excluded.dataset_version;
delete from allowed_record where dataset_version <> '07d286fdcf78cee0';

delete from editable_field where field not in ('runway_months', 'mrr_usd', 'mom_growth_pct', 'monthly_churn_pct', 'pmf_score_pct', 'ltv_cac_ratio');
insert into editable_field (field, min_value, max_value, unit) values
  ('runway_months', 0, 60, 'months'),
  ('mrr_usd', 0, 50000000, 'USD'),
  ('mom_growth_pct', -100, 500, '%'),
  ('monthly_churn_pct', 0, 100, '%'),
  ('pmf_score_pct', 0, 100, '%'),
  ('ltv_cac_ratio', 0, 100, 'x')
on conflict (field) do update set min_value = excluded.min_value, max_value = excluded.max_value, unit = excluded.unit;
commit;
